//! AXIS emit: tablegen domain (split from the former monolithic emit.rs).

use super::common::*;

pub fn emit_tablegen(document: &Document) -> String {
    let extension = tablegen_ident(&document.extension.name);
    let mut out = String::new();
    out.push_str(&format!(
        "// Generated by AXIS from extension {}.\n",
        document.extension.name
    ));
    out.push_str(&format!("// {}\n\n", document.extension.description));
    out.push_str(&format!(
        "class {}Inst<bits<7> funct7, bits<3> funct3, bits<7> opcode, string opcodestr, dag outs, dag ins, string argstr>\n",
        extension
    ));
    out.push_str("  : RVInst<outs, ins, opcodestr, argstr, [], InstFormatR> {\n");
    out.push_str("  bits<5> rd;\n");
    out.push_str("  bits<5> rs1;\n");
    out.push_str("  bits<5> rs2;\n");
    out.push_str("  let Inst{31-25} = funct7;\n");
    out.push_str("  let Inst{24-20} = rs2;\n");
    out.push_str("  let Inst{19-15} = rs1;\n");
    out.push_str("  let Inst{14-12} = funct3;\n");
    out.push_str("  let Inst{11-7} = rd;\n");
    out.push_str("  let Opcode = opcode;\n");
    out.push_str("}\n\n");
    for instruction in &document.instructions {
        let def_name = tablegen_ident(&instruction.mnemonic);
        let (outs, ins, argstr) = tablegen_operands(instruction);
        out.push_str(&format!("// mnemonic: {}\n", instruction.mnemonic));
        out.push_str(&format!("// format: {}\n", instruction.format));
        out.push_str(&format!("// category: {}\n", instruction.category));
        out.push_str(&format!(
            "// latency_cycles: {}\n",
            instruction.latency_cycles
        ));
        out.push_str(&format!(
            "// throughput_per_cycle: {}\n",
            instruction.throughput_per_cycle
        ));
        out.push_str(&format!(
            "// intrinsic: {}\n",
            intrinsic_symbol(instruction)
        ));
        out.push_str(&format!("// asm: {}\n", instruction_asm(instruction)));
        out.push_str(&format!(
            "// decode_key: opcode=0x{:02x}, func3={}, func7={}\n",
            instruction.opcode, instruction.func3, instruction.func7
        ));
        out.push_str(&format!(
            "def {} : {}Inst<0b{:07b}, 0b{:03b}, 0b{:07b}, \"{}\", {}, {}, \"{}\">;\n",
            def_name,
            extension,
            instruction.func7,
            instruction.func3,
            instruction.opcode,
            tablegen_opcode_string(instruction),
            outs,
            ins,
            argstr
        ));
    }
    out
}

pub fn emit_intrinsics(document: &Document) -> String {
    let guard = format!(
        "PCE_ADL_{}_INTRINSICS_H",
        tablegen_ident(&document.extension.name).to_ascii_uppercase()
    );
    let mut out = String::new();
    out.push_str("/* Generated by AXIS. */\n");
    out.push_str(&format!("#ifndef {guard}\n#define {guard}\n\n"));
    out.push_str("#include <stdint.h>\n\n");
    for instruction in &document.instructions {
        let name = intrinsic_symbol(instruction);
        let macro_prefix = intrinsic_macro_prefix(instruction);
        out.push_str(&format!(
            "#define {macro_prefix}_OPCODE 0x{:02X}u\n",
            instruction.opcode
        ));
        out.push_str(&format!(
            "#define {macro_prefix}_FUNC3 {}u\n",
            instruction.func3
        ));
        out.push_str(&format!(
            "#define {macro_prefix}_FUNC7 {}u\n",
            instruction.func7
        ));
        out.push_str(&format!(
            "#define {macro_prefix}_LATENCY_CYCLES {}u\n",
            instruction.latency_cycles
        ));
        let return_type = intrinsic_return_type(instruction);
        let params = intrinsic_params(instruction);
        out.push_str(&format!("{return_type} {name}({params});\n"));
        out.push('\n');
    }
    out.push_str(&format!("\n#endif /* {guard} */\n"));
    out
}

fn tablegen_operands(instruction: &Instruction) -> (String, String, String) {
    let outs = tablegen_operand_dag(
        "outs",
        instruction.operands.iter().filter(|operand| operand.output),
    );
    let ins = tablegen_operand_dag(
        "ins",
        instruction.operands.iter().filter(|operand| operand.input),
    );
    let arg_names: Vec<String> = instruction
        .operands
        .iter()
        .filter(|operand| operand.input)
        .map(|operand| format!("${}", operand.name))
        .collect();
    (outs, ins, arg_names.join(", "))
}

fn tablegen_operand_dag<'a>(kind: &str, operands: impl Iterator<Item = &'a Operand>) -> String {
    let entries: Vec<String> = operands
        .map(|operand| format!("{}:${}", tablegen_operand_class(operand), operand.name))
        .collect();
    if entries.is_empty() {
        format!("({kind})")
    } else {
        format!("({kind} {})", entries.join(", "))
    }
}

fn tablegen_operand_class(operand: &Operand) -> &'static str {
    match operand.kind.as_str() {
        "imm" | "immediate" => "simm12",
        "pred" | "predicate" => "uimm1",
        _ => "GPR",
    }
}

fn intrinsic_symbol(instruction: &Instruction) -> String {
    if instruction.intrinsic.is_empty() {
        format!("pce_{}", instruction.mnemonic.to_ascii_lowercase())
    } else {
        instruction
            .intrinsic
            .strip_prefix("llvm.")
            .unwrap_or(&instruction.intrinsic)
            .replace('.', "_")
    }
}

fn intrinsic_macro_prefix(instruction: &Instruction) -> String {
    format!("PCE_ADL_{}", tablegen_ident(&instruction.mnemonic))
}

fn intrinsic_return_type(instruction: &Instruction) -> String {
    instruction
        .operands
        .iter()
        .find(|operand| operand.output)
        .map(|operand| c_type_for_width(operand.width))
        .unwrap_or_else(|| "void".to_string())
}

fn intrinsic_params(instruction: &Instruction) -> String {
    let params: Vec<String> = instruction
        .operands
        .iter()
        .filter(|operand| operand.input)
        .map(|operand| format!("{} {}", c_type_for_width(operand.width), operand.name))
        .collect();
    if params.is_empty() {
        "void".to_string()
    } else {
        params.join(", ")
    }
}

fn c_type_for_width(width: u32) -> String {
    match width {
        0..=8 => "uint8_t",
        9..=16 => "uint16_t",
        17..=32 => "uint32_t",
        33..=64 => "uint64_t",
        _ => "const void *",
    }
    .to_string()
}
